    publishPrototype("vision", "__bro_native.vision.NormalEstimator", "NormalEstimatorProto");
    publishPrototype("vision", "__bro_native.vision.Hed", "HedProto");
    publishPrototype("vision", "__bro_native.vision.Lineart", "LineartProto");
    publishPrototype("vision", "__bro_native.vision.Mlsd", "MlsdProto");
    publishPrototype("vision", "__bro_native.vision.Openpose", "OpenposeProto");
